            let t = 0, l = 0;
            let el = context.element.topArea;
            while(el){
                t += el.scrollTop;
                l += el.scrollLeft;
                el = el.parentElement;
            }
            el = this._shadowRoot ? this._shadowRoot.host : null;
            while(el){
                t += el.scrollTop;
                l += el.scrollLeft;
                el = el.parentElement;
            }
            return {
                top: t,
                left: l
            };
